{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "DX-9065a, a non-peptidic small molecule with strong basic amidino groups and a carboxylic acid, has human absolute oral bioavailability of only 2–3%, directly supporting low F for the query's benzamidine–carboxylate zwitterionic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Peramivir, which combines a guanidine, carboxylic acid, cyclohexyl, and amide functionalities, has human oral bioavailability ≤3%, supporting low F for the query's similar polar ionizable framework.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "An amidinophenyl carboxylate analogue was reported to have absolute bioavailability not high enough for oral use in humans, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Pentamidine, a diamidine drug, has poor oral bioavailability in humans, supporting low F for the query's amidine-containing structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "L-arginine, a guanidine/carboxylate amino acid, can reach ~68% oral bioavailability at 6 g in humans, providing some contradictory evidence that ionizable guanidine/acid motifs are not inherently non-absorbable; however, the query is a larger peptidomimetic benzamidine rather than a transporter-recognized amino acid.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a zwitterionic benzamidine–carboxylate peptidomimetic. High-transfer human evidence from DX-9065a (F=2–3%), peramivir (F≤3%), and an amidinophenyl carboxylate analogue (not orally bioavailable) consistently indicates very low oral bioavailability. Contradictory high-F examples such as L-arginine are less structurally aligned or rely on specialized absorption mechanisms. Therefore predict low F (<20%).",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "All retrieved human F data are from fasted or unspecified conditions; the query is assessed under fed state, and food effects on this zwitterionic scaffold are unknown.",
    "L-arginine high-F data reflect a natural amino acid with dedicated transporters, limiting direct extrapolation to the query's benzamidine peptidomimetic."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

